USE mccollins_shipping; SET time_zone='+00:00';
DELIMITER $$
DROP PROCEDURE IF EXISTS p8col$$
CREATE PROCEDURE p8col(IN t VARCHAR(64),IN c VARCHAR(64),IN d TEXT) BEGIN IF NOT EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=t AND COLUMN_NAME=c) THEN SET @q=CONCAT('ALTER TABLE `',t,'` ADD COLUMN `',c,'` ',d);PREPARE s FROM @q;EXECUTE s;DEALLOCATE PREPARE s;END IF;END$$
DELIMITER ;
CALL p8col('trips','carrier_company_id','BIGINT UNSIGNED NULL AFTER assignment_id');CALL p8col('trips','carrier_user_id','BIGINT UNSIGNED NULL AFTER carrier_company_id');CALL p8col('trips','origin_address_id','BIGINT UNSIGNED NULL AFTER truck_id');CALL p8col('trips','destination_address_id','BIGINT UNSIGNED NULL AFTER origin_address_id');CALL p8col('trips','planned_departure_at','DATETIME(6) NULL AFTER destination_address_id');CALL p8col('trips','planned_arrival_at','DATETIME(6) NULL AFTER planned_departure_at');CALL p8col('trips','driver_ready_at','DATETIME(6) NULL AFTER planned_arrival_at');CALL p8col('trips','arrived_at','DATETIME(6) NULL AFTER dispatched_at');CALL p8col('trips','delivered_at','DATETIME(6) NULL AFTER arrived_at');CALL p8col('trips','dispatched_by_user_id','BIGINT UNSIGNED NULL AFTER delivered_at');CALL p8col('trips','last_status_by_user_id','BIGINT UNSIGNED NULL AFTER dispatched_by_user_id');
CALL p8col('stops','trip_id','BIGINT UNSIGNED NULL AFTER stop_ref');CALL p8col('stops','sequence_no','INT UNSIGNED NULL AFTER trip_id');CALL p8col('stops','stop_type','VARCHAR(24) NULL AFTER sequence_no');CALL p8col('stops','name','VARCHAR(191) NULL AFTER stop_type');CALL p8col('stops','address_line','VARCHAR(255) NULL AFTER name');CALL p8col('stops','city','VARCHAR(120) NULL AFTER address_line');CALL p8col('stops','planned_at','DATETIME(6) NULL AFTER city');CALL p8col('stops','instructions','VARCHAR(500) NULL AFTER planned_at');
CALL p8col('shipment_milestones','shipment_id','BIGINT UNSIGNED NULL AFTER shipment_milestone_ref');CALL p8col('shipment_milestones','trip_id','BIGINT UNSIGNED NULL AFTER shipment_id');CALL p8col('shipment_milestones','milestone_code','VARCHAR(32) NULL AFTER trip_id');CALL p8col('shipment_milestones','occurred_at','DATETIME(6) NULL AFTER milestone_code');CALL p8col('shipment_milestones','actor_user_id','BIGINT UNSIGNED NULL AFTER occurred_at');
DROP PROCEDURE p8col;
DELIMITER $$
DROP PROCEDURE IF EXISTS p8idx$$
CREATE PROCEDURE p8idx(IN t VARCHAR(64),IN n VARCHAR(64),IN c TEXT,IN u BOOLEAN) BEGIN IF NOT EXISTS(SELECT 1 FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=t AND INDEX_NAME=n) THEN SET @q=CONCAT('ALTER TABLE `',t,'` ADD ',IF(u,'UNIQUE ',''),'INDEX `',n,'` (',c,')');PREPARE s FROM @q;EXECUTE s;DEALLOCATE PREPARE s;END IF;END$$
DELIMITER ;
CALL p8idx('shipments','uq_shipments_assignment','`active_assignment_id`',TRUE);CALL p8idx('trips','uq_trips_assignment','`assignment_id`',TRUE);CALL p8idx('stops','uq_stops_trip_sequence','`trip_id`,`sequence_no`',TRUE);CALL p8idx('shipment_milestones','ix_milestones_shipment','`shipment_id`,`occurred_at`',FALSE);DROP PROCEDURE p8idx;
DELIMITER $$
DROP PROCEDURE IF EXISTS p8fk$$
CREATE PROCEDURE p8fk(IN t VARCHAR(64),IN n VARCHAR(64),IN c VARCHAR(64),IN rt VARCHAR(64),IN rc VARCHAR(64)) BEGIN IF NOT EXISTS(SELECT 1 FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME=t AND CONSTRAINT_NAME=n) THEN SET @q=CONCAT('ALTER TABLE `',t,'` ADD CONSTRAINT `',n,'` FOREIGN KEY (`',c,'`) REFERENCES `',rt,'` (`',rc,'`)');PREPARE s FROM @q;EXECUTE s;DEALLOCATE PREPARE s;END IF;END$$
DELIMITER ;
CALL p8fk('shipments','fk_shipments_assignment','active_assignment_id','assignments','assignment_id');CALL p8fk('trips','fk_trips_carrier_company','carrier_company_id','companies','company_id');CALL p8fk('trips','fk_trips_carrier_user','carrier_user_id','users','user_id');CALL p8fk('trips','fk_trips_origin','origin_address_id','addresses','address_id');CALL p8fk('trips','fk_trips_destination','destination_address_id','addresses','address_id');CALL p8fk('stops','fk_stops_trip','trip_id','trips','trip_id');CALL p8fk('shipment_milestones','fk_milestones_shipment','shipment_id','shipments','shipment_id');CALL p8fk('shipment_milestones','fk_milestones_trip','trip_id','trips','trip_id');DROP PROCEDURE p8fk;
SELECT 'Phase 8 alignment completed' result;
